CREATE POLICY "active members read books" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='learning-books' AND public.has_active_access(auth.uid()));
CREATE POLICY "owner uploads books" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='learning-books' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "owner updates books" ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='learning-books' AND public.has_role(auth.uid(),'admin')) WITH CHECK(bucket_id='learning-books' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "owner deletes books" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='learning-books' AND public.has_role(auth.uid(),'admin'));